-- 개수 쿼리를 따로 만든다

@Override
public Page<MemberTeamDto> searchPageComplex(MemberSearchCondition cond,
                                             Pageable pageable) {
    BooleanExpression predicate = Expressions.allOf(
            usernameEq(cond.getUsername()),
            ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)          // 팀 이름을 보여 주려고
            .where(predicate)
            .orderBy(member.id.asc())
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .fetch();

    JPAQuery<Long> countQuery = queryFactory
            .select(member.count())
            .from(member)                          // 조인이 없다
            .where(predicate);

    return PageableExecutionUtils.getPage(content, pageable,
            countQuery::fetchOne);
}

--   조건은 같고 조인·정렬·select 가 다르다
