-- 시간을 잰다

@Test
@Transactional
void 개수_시간() {
    for (int i = 0; i < 30000; i++) {
        Member m = new Member("p" + i, i % 50);
        if (i % 2 == 0) m.setTeam(teamA);
        em.persist(m);
    }
    em.flush(); em.clear();

    for (String kind : List.of("조인 있음", "조인 없음")) {
        em.clear();
        long t = System.nanoTime();
        if (kind.equals("조인 있음")) {
            queryFactory.select(member.count()).from(member)
                    .leftJoin(member.team, team)
                    .where(member.age.goe(20)).fetchOne();
        } else {
            queryFactory.select(member.count()).from(member)
                    .where(member.age.goe(20)).fetchOne();
        }
        System.out.printf("%-10s %d ms%n", kind,
                (System.nanoTime() - t) / 1_000_000);
    }
}

