@Override
public Page<MemberTeamDto> searchPageWithTeam(MemberSearchCondition cond,
                                              Pageable pageable) {
    BooleanExpression predicate = Expressions.allOf(
            teamNameEq(cond.getTeamName()),        // 팀 조건이다
            ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(...))
            .from(member).leftJoin(member.team, team)
            .where(predicate)
            .orderBy(member.id.asc())
            .offset(pageable.getOffset()).limit(pageable.getPageSize())
            .fetch();

    JPAQuery<Long> countQuery = queryFactory
            .select(member.count())
            .from(member)
            .leftJoin(member.team, team)           // 남겨야 한다
            .where(predicate);

    return PageableExecutionUtils.getPage(content, pageable,
            countQuery::fetchOne);
}

