@Test
@Transactional
void 세_경우() {
    MemberSearchCondition cond = new MemberSearchCondition();
    cond.setAgeGoe(20);

    record C(String name, PageRequest req) {}
    for (C c : List.of(
            new C("첫 쪽 여유", PageRequest.of(0, 10)),
            new C("가운데",     PageRequest.of(1, 2)),
            new C("마지막",     PageRequest.of(2, 2)))) {
        em.clear();
        sqlCounter.clear();
        memberRepository.searchPageComplex(cond, c.req());
        System.out.printf("%-10s %d개%n", c.name(), sqlCounter.count());
    }
}

